33YE;EACE,aAAA;AhC83YJ;;AgC/3YE;EACE,aAAA;AhCk4YJ;;AgCn4YE;EACE,aAAA;AhCs4YJ;;AgCv4YE;EACE,aAAA;AhC04YJ;;AgC34YE;EACE,aAAA;AhC84YJ;;AgC/4YE;EACE,aAAA;AhCk5YJ;;AgCn5YE;EACE,aAAA;AhCs5YJ;;AgCv5YE;EACE,aAAA;AhC05YJ;;AgC35YE;EACE,aAAA;AhC85YJ;;AiC77YA;;;;EAAA;AASA;EACE,0CAAA;EACA,0DAAA;EAEA,8EAAA;EACA,mDAAA;AjC27YF;;AiCv7YE;EACE,kCAAA;EACA,kBAAA;EACA,gBAAA;EACA,mBH6BqB;EG5BrB,oEAAA;AjC07YJ;AiCt7YA;EACE,qCAAA;EACA,eAAA;AjCw7YF;;AiCr7YA;EACE,qCAAA;AjCw7YF;;AiCr7YA;EACE,eAAA;AjCw7YF","file":"style.css","sourcesContent":["@charset \"UTF-8\";\n/*!------------------------------------------------------------------\n[MAIN STYLESHEET]\n\nPROJECT:\tThomson\nVERSION:\t1.0\n-------------------------------------------------------------------*/\n/*------------------------------------------------------------------\n[TABLE OF CONTENTS]\n-------------------------------------------------------------------*/\n@import url(\"https://fonts.googleapis.com/css?family=Lato:400,600,700|Work+Sans:400,700,800\");\nhtml {\n  overflow-x: hidden;\n}\n\nbody {\n  font-family: \"Lato\", sans-serif;\n  -webkit-font-smoothing: antialiased;\n  font-size: 16px;\n  font-weight: 400;\n  letter-spacing: 0.166667px;\n  line-height: 1.7em;\n  color: #818385;\n}\n\np {\n  color: #818385;\n}\n\nh1, .h1, h2, .h2, h3, .h3, h4, .h4, h5, .h5, h6, .h6 {\n  font-family: \"Work Sans\", sans-serif;\n  color: #000;\n  font-weight: 600;\n}\n\nh1, .h1 {\n  font-size: 45px;\n  text-transform: none;\n}\n\nh2, .h2 {\n  font-size: 42px;\n  line-height: 52px;\n}\n\nh3, .h3 {\n  font-size: 24px;\n  line-height: 34px;\n}\n\nh4, .h4 {\n  font-size: 20px;\n  line-height: 30px;\n}\n\nh5, .h5 {\n  font-size: 16px;\n  line-height: 26px;\n}\n\nh6, .h6 {\n  font-size: 14px;\n}\n\n.text-sm {\n  font-size: 14px;\n}\n\n.section {\n  padding: 120px 0px;\n}\n\n.section-sm {\n  padding: 60px 0px;\n}\n\n.btn {\n  padding: 18px 38px;\n  border: 2px solid transparent;\n  text-transform: uppercase;\n  border-radius: 0px;\n  font-size: 14px;\n  line-height: 14px;\n  font-weight: 600;\n  box-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n}\n.btn:focus {\n  outline: 0px;\n  border: 0px;\n  box-shadow: none;\n}\n\n.btn-main {\n  background: #f44336;\n  color: #fff;\n}\n.btn-main:hover {\n  color: #fff !important;\n  background: #000;\n}\n\n.btn-black {\n  background: #000;\n  color: #fff;\n}\n.btn-black:hover {\n  background: #f44336;\n  color: #fff;\n}\n\n.btn-white {\n  background: #fff;\n  color: #000;\n  border-color: #fff;\n}\n.btn-white:hover {\n  background: transparent;\n  color: #fff;\n}\n\na {\n  color: #000;\n  -webkit-transition: all 0.25s ease;\n  -moz-transition: all 0.25s ease;\n  -ms-transition: all 0.25s ease;\n  -o-transition: all 0.25s ease;\n  transition: all 0.25s ease;\n}\na:hover {\n  color: #f44336;\n  text-decoration: none;\n  outline: none;\n}\n\n.bg-primary {\n  background: #f44336 !important;\n}\n\n.bg-secondary {\n  background: #f7f7f7 !important;\n}\n\n.bg-extra {\n  background: #e8eefb !important;\n}\n\n.text-color {\n  color: #f44336;\n}\n\n.page-title h1 {\n  position: relative;\n  padding-bottom: 30px;\n}\n.page-title h1:after {\n  position: absolute;\n  content: \"\";\n  left: 50%;\n  bottom: 0px;\n  width: 40px;\n  height: 2px;\n  margin-left: -25px;\n  background: #f44336;\n}\n\n@media (max-width: 575px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n@media (max-width: 400px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n.cd-headline.clip span {\n  padding: 0px;\n}\n\n.banner .cd-headline {\n  font-size: 56px;\n  line-height: 70px;\n}\n\n.banner-3 {\n  position: relative;\n}\n\n.main-nav .header-top-socials a {\n  text-transform: uppercase;\n  letter-spacing: 1px;\n  font-size: 14px;\n  padding: 20px 6px;\n}\n\n.navbar-nav .nav-link {\n  padding: 20px 15px !important;\n  text-transform: uppercase;\n  font-size: 14px;\n  letter-spacing: 1px;\n  font-weight: 700;\n}\n\nul.dropdown-menu {\n  background: rgb(21, 21, 21);\n  border-radius: 0px;\n  margin: 0px;\n  padding: 0px;\n}\n\nul.dropdown-menu > li > a, .navbar ul ul ul.dropdown-menu li .nav-link {\n  font-size: 12px;\n  line-height: 22px;\n  display: block;\n  position: relative;\n  z-index: 1;\n  padding-left: 15px;\n  -webkit-transition: all 0.3s ease-in-out;\n  transition: all 0.3s ease-in-out;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #27243e;\n  color: #fff;\n  text-transform: uppercase;\n}\nul.dropdown-menu > li > a:hover, .navbar ul ul ul.dropdown-menu li .nav-link:hover {\n  color: #f44336;\n}\n\n.dropdown-item:focus, .dropdown-item:hover {\n  color: #fff;\n  text-decoration: none;\n  background-color: transparent;\n}\n\n.dropdown-menu {\n  border-radius: 0;\n  -moz-border-radius: 0;\n  -webkit-border-radius: 0;\n  -o-border-radius: 0;\n  -ms-border-radius: 0;\n  padding: 0;\n  border: 0;\n  display: block;\n  opacity: 0;\n  visibility: hidden;\n  min-width: 210px;\n  transform: scaleY(0);\n  -webkit-transform: scaleY(0);\n  -moz-transform: scaleY(0);\n  -ms-transform: scaleY(0);\n  -o-transform: scaleY(0);\n  transform-origin: center top 0;\n  -webkit-transform-origin: center top 0;\n  -moz-transform-origin: center top 0;\n  -ms-transform-origin: center top 0;\n  -o-transform-origin: center top 0;\n  transition: all 0.3s ease-in-out 0s;\n  -webkit-transition: all 0.3s ease-in-out 0s;\n  -moz-transition: all 0.3s ease-in-out 0s;\n  -ms-transition: all 0.3s ease-in-out 0s;\n  -o-transition: all 0.3s ease-in-out 0s;\n  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);\n  -webkit-box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);\n  -moz-box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);\n  -ms-box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);\n  -o-box-shadow: 0 6px 12px rgba(0, 0, 0, 0.175);\n}\n\n.dropdown:hover .dropdown-menu {\n  opacity: 1;\n  visibility: visible;\n  -webkit-transform: scaleY(1);\n  -moz-transform: scaleY(1);\n  -ms-transform: scaleY(1);\n  -o-transform: scaleY(1);\n}\n\n@media (max-width: 575px) {\n  