1;\n}\n\n.number {\n  display: block;\n  font-size: 24px;\n  font-weight: 700;\n}\n\n.label {\n  display: block;\n  font-size: 13px;\n  color: #777;\n}\n\n.portfolio-info {\n  padding: 18px;\n}\n\n.project-stats {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 1.3vw;\n}\n\n.project-description {\n  font-size: 0.9rem;\n  line-height: 1.5;\n  color: #6c757d;\n  border-top: 1px solid #eee;\n  padding-top: 12px;\n  margin-top: 10px;\n}\n\n.stat {\n  flex: 1;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 6px;\n  text-align: center;\n  font-size: 1.3vw;\n  font-weight: 500;\n}\n\n.portfolio-info {\n  padding: 24px 18px;\n}\n\n.project-stats {\n  display: flex;\n  justify-content: center;\n  gap: 1vw;\n}\n\n.stat {\n  flex: 1;\n  display: flex;\n  flex-direction: column; /* Icona sopra, testo sotto */\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  gap: 8px;\n  margin-top: 5px;\n}\n\n.stat i {\n  font-size: 1.2em;\n  color: #4a90e2;\n}\n\n.stat span {\n  font-size: 0.7em;\n  font-weight: 500;\n  white-space: nowrap;\n}\n\n.portfolio-card {\n  height: 460px;\n}\n\n.portfolio-card .image img {\n  height: 160px;\n  object-fit: cover;\n}\n\n.portfolio-info {\n  padding: 10px 12px 12px;\n}\n\n.project-title {\n  font-size: 1.5rem;\n  margin-top: 5px;\n  margin-bottom: 10px;\n  text-align: center;\n  font-weight: 600;\n  line-height: 1.2em;\n}\n\n.project-stats {\n  font-size: 0.8rem;\n}\n\n.project-stats .stat {\n  margin-right: 8px;\n}\n\n.mb-4 {\n  margin-bottom: 1rem !important;\n}\n\n@media (max-width: 720px) {\n  .project-stats {\n    margin-top: 20px;\n    margin-bottom: 0px;\n  }\n  .stat {\n    font-size: 2.4vw;\n  }\n}\n.portfolio-options {\n  margin-bottom: 1em !important;\n}\n\n/* ============================================\n   BANNER: contenitore principale\n   ============================================ */\n.banner {\n  position: relative;\n  min-height: 70vh;\n  display: flex;\n  align-items: center;\n  overflow: hidden;\n}\n\n/* ============================================\n   VIDEO BACKGROUND: colonna centrata\n   ============================================ */\n.video-background {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 95%; /* 👈 LARGHEZZA DELLA COLONNA (regolabile) */\n  height: 95%; /* 👈 ALTEZZA DELLA COLONNA (regolabile) */\n  min-width: 70%;\n  max-width: 1200px; /* Larghezza massima */\n  max-height: 800px; /* Altezza massima */\n  z-index: 0;\n  overflow: hidden;\n  border-radius: 20px; /* Angoli arrotondati (opzionale) */\n  box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n}\n\n/* ============================================\n   VIDEO: centrato e tagliato all'interno della colonna\n   ============================================ */\n.video-background video {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  min-width: 100%;\n  min-height: 100%;\n  width: auto;\n  height: auto;\n  object-fit: cover;\n  opacity: 60%;\n}\n\n/* Meta' schermo */\n@media (max-width: 720px) {\n  .video-background {\n    max-height: 80%;\n    max-width: 100%;\n  }\n  .banner .cd-headline {\n    font-size: 24px !important;\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 50vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n}\n/* \n==================================\nTelefono\n==================================\n*/\n@media (max-width: 520px) {\n  .video-background {\n    max-height: 100%;\n    max-width: 100%;\n    border-radius: 0px;\n    width: 100%;\n    height: 100%;\n    box-shadow: inset 0px 0px 30px 30px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 30vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n  /*\n  ==================================\n  Portfolio-home\n  ==================================\n  */\n  label.btn {\n    font-size: 13px;\n    padding: 20px 10px 10px 0px !important;\n  }\n  p.short-text {\n    display: contents;\n  }\n  p.full-text {\n    display: none;\n  }\n  .stat {\n    font-size: 3vw;\n  }\n}\n@media (min-width: 521px) {\n  p.short-text {\n    display: none;\n  }\n  p.full-text {\n    display: contents;\n  }\n}\n/* ============================================\n   CONTENUTO TESTUALE: sopra il video\n   ============================================ */\n.banner .container {\n  position: relative;\n  z-index: 1;\n  width: 100%;\n}\n\n/* Colonna del testo centrata con larghezza controllata */\n.banner .container .col-lg-10 {\n  margin: 0 auto;\n  float: none;\n}\n\n/* Testo in contrasto con il video */\n.banner h2,\n.banner p {\n  color: white;\n  text-shadow: 0 2px 15px rgba(0, 0, 0, 0.7);\n}\n\n.copy-btn {\n  background: transparent;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n  color: inherit; /* Eredita il colore dal testo circostante */\n  font: inherit; /* Eredita il font */\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n\n.copy-btn:hover {\n  color: #f44336;\n}\n\n.toast {\n  position: fixed;\n  bottom: 30px;\n  left: 50%;\n  transform: translateX(-50%) translateY(100px);\n  background: #ffffff;\n  color: #222;\n  padding: 14px 32px;\n  border-radius: 30px;\n  font-size: 0.95rem;\n  font-weight: 500;\n  letter-spacing: 0.3px;\n  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.35);\n  opacity: 0;\n  transition: opacity 0.4s ease, transform 0.4s ease;\n  z-index: 9999;\n  pointer-events: none;\n  white-space: nowrap;\n}\n\n.toast.show {\n  opacity: 1;\n  transform: translateX(-50%) translateY(0);\n}\n\n/* Cambiano in base alla grandezza del dispositivo */\n/* Su schermi piccoli, abbrevia il testo */\n@media (max-width: 768px) {\n  .stat .full-text {\n    display: none;\n  }\n  .stat .short-text {\n    display: inline;\n  }\n}\n@media (min-width: 769px) {\n  .stat .full-text {\n    display: inline;\n  }\n  .stat .short-text {\n    display: none;\n  }\n}\n@media (max-width: 991px) {\n  .footer-widget {\n    margin-top: 1em !important;\n  }\n}\n@media (max-width: 768px) {\n  .navbar-nav {\n    flex-wrap: nowrap !important;\n  }\n  .navbar-nav .nav-item {\n    white-space: nowrap;\n  }\n}\n.rainbow-icon {\n  display: inline-block;\n  font-size: 1.2rem;\n  background: linear-gradient(90deg, #ff0000, #ff7700, #ffff00, #00ff00, #0000ff, #8b00ff, #ff0000);\n  background-size: 300% 100%;\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  background-clip: text;\n  animation: rainbowScroll 4s linear infinite, floatXY 1s linear infinite;\n}\n\n@keyframes rainbowScroll {\n  0% {\n    background-position: 0% 50%;\n  }\n  100% {\n    background-position: 300% 50%;\n  }\n}\n@keyframes floatXY {\n  /*0%, 100% { transform: rotate(0deg); }\n  25% { transform: rotate(-10deg);}\n  50% { transform: rotate(0deg); }\n  75% { transform: rotate(10deg); }*/\n  0%, 100% {\n    transform: scale(1);\n  }\n  50% {\n    transform: scale(1.2);\n  }\n}\n.jump-text {\n  font-size: 2em;\n  display: inline-block;\n}\n\n.jump-text span {\n  display: inline-block;\n  animation: jump 0.8s ease-in-out infinite, rainbow 3s linear infinite;\n}\n\n.jump-text span:nth-child(1) {\n  animation-delay: 0s, 0s;\n}\n\n.jump-text span:nth-child(2) {\n  animation-delay: 0.1s, 0.1s;\n}\n\n.jump-text span:nth-child(3) {\n  animation-delay: 0.2s, 0.2s;\n}\n\n.jump-text span:nth-child(4) {\n  animation-delay: 0.3s, 0.3s;\n}\n\n.jump-text span:nth-child(5) {\n  animation-delay: 0.4s, 0.4s;\n}\n\n.jump-text span:nth-child(6) {\n  animation-delay: 0.5s, 0.5s;\n}\n\n.jump-text span:nth-child(7) {\n  animation-delay: 0.6s, 0.6s;\n}\n\n.jump-text span:nth-child(8) {\n  animation-delay: 0.7s, 0.7s;\n}\n\n.jump-text span:nth-child(9) {\n  animation-delay: 0.8s, 0.8s;\n}\n\n.jump-text span:nth-child(10) {\n  animation-delay: 0.9s, 0.9s;\n}\n\n.jump-text span:nth-child(11) {\n  animation-delay: 1s, 1s;\n}\n\n.jump-text span:nth-child(12) {\n  animation-delay: 1.1s, 1.1s;\n}\n\n.jump-text span:nth-child(13) {\n  animation-delay: 1.2s, 1.2s;\n}\n\n.jump-text span:nth-child(14) {\n  animation-delay: 1.3s, 1.3s;\n}\n\n.jump-text span:nth-child(15) {\n  animation-delay: 1.4s, 1.4s;\n}\n\n.jump-text span:nth-child(16) {\n  animation-delay: 1.5s, 1.5s;\n}\n\n.jump-text span:nth-child(17) {\n  animation-delay: 1.6s, 1.6s;\n}\n\n.jump-text span:nth-child(18) {\n  animation-delay: 1.7s, 1.7s;\n}\n\n.jump-text span:nth-child(19) {\n  animation-delay: 1.8s, 1.8s;\n}\n\n.jump-text span:nth-child(20) {\n  animation-delay: 1.9s, 1.9s;\n}\n\n@keyframes jump {\n  0%, 100% {\n    transform: translateY(0);\n  }\n  50% {\n    transform: translateY(-8px);\n  }\n}\n@keyframes rainbow {\n  0% {\n    color: #ff0000;\n  }\n  17% {\n    color: #ff7700;\n  }\n  33% {\n    color: #ffff00;\n  }\n  50% {\n    color: #00ff00;\n  }\n  67% {\n    color: #0000ff;\n  }\n  83% {\n    color: #8b00ff;\n  }\n  100% {\n    color: #ff0000;\n  }\n}\n.project-description-full {\n  padding: 40px 0;\n  border-top: 2px solid #e8e8e8;\n}\n\n.border-line {\n  width: 50%;\n  height: 2px;\n  background: #e8e8e8;\n  margin: 0 auto;\n}\n\n.project-description-full h3 {\n  font-size: 1.8rem;\n  font-weight: 700;\n  letter-spacing: -0.5px;\n  margin-bottom: 20px;\n  color: #1a1a1a;\n}\n\n.project-description-full p {\n  font-size: 1.05rem;\n  line-height: 1.9;\n  color: #444;\n  margin-bottom: 18px;\n}\n\n.fa-solid,\n.fa-regular,\n.fa-brands,\n.fa-classic,\n.fas,\n.far,\n.fab,\n.fa {\n  --_fa-family: var(--fa-family, var(--fa-style-family, 'Font Awesome 7 Free'));\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  display: var(--fa-display, inline-block);\n  font-family: var(--_fa-family);\n  font-feature-settings: normal;\n  font-style: normal;\n  font-synthesis: none;\n  font-variant: normal;\n  font-weight: var(--fa-style, 900);\n  line-height: 1;\n  text-align: center;\n  text-rendering: auto;\n  width: var(--fa-width, 1.25em);\n}\n\n:is(.fas,\n.far,\n.fab,\n.fa-solid,\n.fa-regular,\n.fa-brands,\n.fa-classic,\n.fa)::before {\n  content: var(--fa)/\"\";\n}\n\n@supports not (content: \"\"/\"\") {\n  :is(.fas,\n  .far,\n  .fab,\n  .fa-solid,\n  .fa-regular,\n  .fa-brands,\n  .fa-classic,\n  .fa)::before {\n    content: var(--fa);\n  }\n}\n.fa-1x {\n  font-size: 1em;\n}\n\n.fa-2x {\n  font-size: 2em;\n}\n\n.fa-3x {\n  font-size: 3em;\n}\n\n.fa-4x {\n  font-size: 4em;\n}\n\n.fa-5x {\n  font-size: 5em;\n}\n\n.fa-6x {\n  font-size: 6em;\n}\n\n.fa-7x {\n  font-size: 7em;\n}\n\n.fa-8x {\n  font-size: 8em;\n}\n\n.fa-9x {\n  font-size: 9em;\n}\n\n.fa-10x {\n  font-size: 10em;\n}\n\n.fa-2xs {\n  font-size: calc(10 / 16 * 1em); /* converts a 10px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 10 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 10 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-xs {\n  font-size: calc(12 / 16 * 1em); /* converts a 12px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 12 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 12 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-sm {\n  font-size: calc(14 / 16 * 1em); /* converts a 14px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 14 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 14 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-lg {\n  font-size: calc(20 / 16 * 1em); /* converts a 20px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 20 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 20 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-xl {\n  font-size: calc(24 / 16 * 1em); /* converts a 24px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 24 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 24 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-2xl {\n  font-size: calc(32 / 16 * 1em); /* converts a 32px size into an em-based value that's relative to the scale's 16px base */\n  line-height: calc(1 / 32 * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc((6 / 32 - 0.375) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n\n.fa-width-auto {\n  --fa-width: auto;\n}\n\n.fa-fw,\n.fa-width-fixed {\n  --fa-width: 1.25em;\n}\n\n.fa-canvas-square {\n  padding-block: 0.125em;\n  margin-block-end: -0.125em;\n}\n\n.fa-canvas-roomy {\n  padding-block: 0.25em;\n  padding-inline: 0.125em;\n  margin-block-end: -0.25em;\n  box-sizing: content-box;\n}\n\n.fa-ul {\n  list-style-type: none;\n  margin-inline-start: var(--fa-li-margin, 2.5em);\n  padding-inline-start: 0;\n}\n\n.fa-ul > li {\n  position: relative;\n}\n\n.fa-li {\n  inset-inline-start: calc(-1 * var(--fa-li-width, 2em));\n  position: absolute;\n  text-align: center;\n  width: var(--fa-li-width, 2em);\n  line-height: inherit;\n}\n\n/* Heads Up: Bordered Icons will not be supported in the future!\n  - This feature will be deprecated in the next major release of Font Awesome (v8)!\n  - You may continue to use it in this version *v7), but it will not be supported in Font Awesome v8.\n*/\n/* Notes:\n* --@{v.$css-prefix}-border-width = 1/16 by default (to render as ~1px based on a 16px default font-size)\n* --@{v.$css-prefix}-border-padding =\n  ** 3/16 for vertical padding (to give ~2px of vertical whitespace around an icon considering it's vertical alignment)\n  ** 4/16 for horizontal padding (to give ~4px of horizontal whitespace around an icon)\n*/\n.fa-border {\n  border-color: var(--fa-border-color, #eee);\n  border-radius: var(--fa-border-radius, 0.1em);\n  border-style: var(--fa-border-style, solid);\n  border-width: var(--fa-border-width, 0.0625em);\n  box-sizing: var(--fa-border-box-sizing, content-box);\n  padding: var(--fa-border-padding, 0.1875em 0.25em);\n}\n\n.fa-pull-left,\n.fa-pull-start {\n  float: inline-start;\n  margin-inline-end: var(--fa-pull-margin, 0.3em);\n}\n\n.fa-pull-right,\n.fa-pull-end {\n  float: inline-end;\n  margin-inline-start: var(--fa-pull-margin, 0.3em);\n}\n\n.fa-beat {\n  animation-name: fa-beat;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-bounce {\n  animation-name: fa-bounce;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, cubic-bezier(0.28, 0.84, 0.42, 1));\n}\n\n.fa-fade {\n  animation-name: fa-fade;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-beat-fade {\n  animation-name: fa-beat-fade;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-flip {\n  animation-name: fa-flip;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1.5s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-flip-360 {\n  animation-name: fa-flip-360;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 1s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-shake {\n  animation-name: fa-shake;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 0.75s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, ease-in-out);\n}\n\n.fa-spin {\n  animation-name: fa-spin;\n  animation-delay: var(--fa-animation-delay, 0s);\n  animation-direction: var(--fa-animation-direction, normal);\n  animation-duration: var(--fa-animation-duration, 2s);\n  animation-iteration-count: var(--fa-animation-iteration-count, infinite);\n  animation-timing-function: var(--fa-animation-timing, linear);\n}\n\n.fa-spin-reverse {\n  --fa-animation-direction: reverse;\n}\n\n.fa-pulse,\n.fa-spin