\n\t        transition: all .25s ease;\n\n\t&:hover{\n\t\tcolor: $primary-color;\n\t\ttext-decoration: none;\n\t\toutline:none;\n\t}\n\n}\n\n.bg-primary{\n\tbackground: $primary-color!important;\n}\n\n.bg-secondary{\n\tbackground: $secondary-color!important;\n}\n.bg-extra{\n\tbackground: $extra-color!important;\n}\n\n.text-color{\n\tcolor: $primary-color;\n}\n\n.page-title{\n\th1{\n\t\tposition: relative;\n\t\tpadding-bottom: 30px;\n\n\t\t&:after{\n\t\t\tposition: absolute;\n\t\t\tcontent:\"\";\n\t\t\tleft: 50%;\n\t\t\tbottom:0px;\n\t\t\twidth: 40px;\n\t\t\theight: 2px;\n\t\t\tmargin-left: -25px;\n\t\t\tbackground: $primary-color;\n\t\t}\n\t}\n}\n\n\n@include mobile{\n\th2, .h2 {\n\t    font-size: 32px;\n\t    line-height: 43px;\n\t}\n}\n\n@include mobile-xs{\n\th2, .h2 {\n\t    font-size: 32px;\n\t    line-height: 43px;\n\t}\n}","@mixin mobile-xs{\n  @media(max-width:400px){\n    @content;\n  }\n}\n@mixin mobile{\n  @media(max-width:575px){\n    @content;\n  }\n}\n@mixin tablet{\n  @media(max-width:767px){\n    @content;\n  }\n}\n@mixin desktop{\n  @media(max-width:991px){\n    @content;\n  }\n}\n@mixin desktop-lg{\n  @media(max-width:1200px){\n    @content;\n  }\n}\n\n@mixin size($size){\n  width: $size; height: $size;\n}",".cd-headline.clip span{\n\tpadding: 0px;\n}\n\n.banner .cd-headline {\n    font-size: 56px;\n    line-height: 70px;\n}\n\n.banner-3{\n\tposition: relative;\n}\n\n",".main-nav {\n\t.header-top-socials{\n\t\ta{\n\t\t\ttext-transform: uppercase;\n\t\t\tletter-spacing: 1px;\n\t\t\tfont-size: 14px;\n\t\t\tpadding: 20px 6px;\n\t\t}\n\t}\n}\n\n.navbar-nav .nav-link {\n\tpadding: 20px 15px!important;\n\ttext-transform: uppercase;\n\tfont-size: 14px;\n\tletter-spacing: 1px;\n    font-weight: 700;\n}\n\nul.dropdown-menu {\n    background: rgba(21,21,21,1);\n    border-radius: 0px;\n    margin: 0px;\n    padding: 0px;\n}\nul.dropdown-menu > li > a, .navbar ul ul ul.dropdown-menu li .nav-link {\n    font-size: 12px;\n    line-height: 22px;\n    display: bl