-group, .btn-group-vertical {\n        display: block;\n    }\n\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n\n\n@include mobile-xs{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n@include tablet{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n@include desktop{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}","\n\n// Portfolio\n// \n.portfolio{\n  padding-bottom: 100px;\n\n  .btn:focus,.btn:hover,.btn.focus.active{\n    box-shadow: none!important;\n\t  outline: 0!important;\n  }\n \n  .btn-group .btn{\n    border-radius: 0px!important;\n    padding-left: 0px;\n    font-weight: 700;\n\n    &:hover{\n    \tcolor: $primary-color;\n    }\n  }\n\n  .btn-group:not(:first-child) > .btn, .btn-group > .btn:not(:first-child) {\n    border-top-left-radius: 0px;\n    border-bottom-left-radius: 0px;\n  }\n\n  .btn.active{\n    color: $primary-color;\n  }\n  \n}\n\n .inner-box{\n  position:relative;\n}\n\n.inner-box .image{\n  position:relative;\n  overflow: hidden;\n}\n\n.inner-box .image img{\n  position:relative;\n  width:100%;\n  display:block;\n   -ms-transition: all 0.3s;\n    -moz-transition: all 0.3s;\n    -webkit-transition: all 0.3s;\n    -o-transition: all 0.3s;\n    transition: all 0.3s;\n}\n\n.inner-box .image .overlay-box{\n    position: absolute;\n    left: 0px;\n    bottom: 0px;\n    right: 0px;\n    top: 0px;\n    z-index: 2;\n    opacity: 0;\n    display: block;\n    -webkit-transition: all .6s ease;\n    -ms-transition: all .6s ease;\n    -o-transition: all .6s ease;\n    transition: all .6s ease;\n    overflow: hidden;\n\n}\n\n.inner-box .image .overlay-box:before{\n  position:absolute;\n  content:'';\n  left:-450px;\n  top:0px;\n  width:100%;\n  height:100%;\n   display:block;\n    opacity:0; \n    -ms-transition: all 0.4s;\n    -moz-transition: all 0.4s;\n    -webkit-transition: all 0.4s;\n    -o-transition: all 0.4s;\n    transition: all 0.4s;\n    background-color:rgba(47, 50, 56 ,.8);\n}\n.inner-box:hover .image img{\n -webkit-transform: scale(1.1);\n    -moz-transform: scale(1.1);\n     -ms-transform: scale(1.1);\n      -o-transform: scale(1.1);\n         transform: scale(1.1);\n}\n.inner-box:hover .image .overlay-box:before{\n  opacity: 1;\n  left: 0px;\n}\n\n\n .inner-box:hover .image .overlay-box{\n  opacity: 1;\n}\n\n .inner-box:hover .image .overlay-box .overlay-content h5{\n      -webkit-transform: translateX(0px);\n         -moz-transform: translateX(0px);\n          -ms-transform: translateX(0px);\n           -o-transform: translateX(0px);\n              transform: translateX(0px);\n}\n .inner-box:hover .image .overlay-box .overlay-content p{\n      -webkit-transform: translateX(0px);\n         -moz-transform: translateX(0px);\n          -ms-transform: translateX(0px);\n           -o-transform: translateX(0px);\n              transform: translateX(0px);\n}\n\n .inner-box .image .overlay-box .overlay-inner{\n    position: absolute;\n    left: 0px;\n    bottom: 30px;\n    z-index:1;\n    padding: 10px 40px;\n}\n\n\n .inner-box .image .overlay-box .overlay-inner .overlay-content{\n   \n    i{\n      font-size: 28px;\n    }\n}\n\n\n .inner-box .image h3{\n  color:$white;\n}\n\n.overlay-content{\n    h5{\n      text-transform: capitalize;\n      background:rgba(255,255,255,0.9);\n      padding: 0px 8px;\n      margin-bottom: 0px;\n      -webkit-transform: translateX(-150px);\n         -moz-transform: translateX(-150px);\n          -ms-transform: translateX(-150px);\n           -o-transform: translateX(-150px);\n              transform: translateX(-150px);\n    -ms-transition: all 0.3s;\n    -moz-transition: all 0.3s;\n    -webkit-transition: all 0.3s;\n    -o-transition: all 0.3s;\n    transition: all 0.3s;\n    }\n\n    p{\n    \tfont-size: 14px;\n      margin-bottom: 0px;\n      padding: 0px 8px;\n      margin-top: 2px;\n      text-transform: capitalize;\n      background: rgba(255,255,255,0.9);\n      color: #2f3238;\n      -webkit-transform: translateX(-150px);\n         -moz-transform: translateX(-150px);\n          -ms-transform: translateX(-150px);\n           -o-transform: translateX(-150px);\n              transform: translateX(-150px);\n    -ms-transition: all 0.5s;\n    -moz-transition: all 0.5s;\n    -webkit-transition: all 0.5s;\n    -o-transition: all 0.5s;\n    transition: all 0.5s;\n    }\n}\n\n\n\n.portfolio-image{\n    width: 60px;\n    height: 60px;\n    display: inline-block;\n    text-align: center;\n    background: $black;\n    color: $white;\n    padding-top: 16px;\n    position: absolute;\n    top: 40%;\n    font-size: 22px;\n    margin-left: -28px;\n    left:50%;\n}\n\n// POrtfolio single\n// \n\n\n.info{\n  a{\n    margin-right: 10px;\n  }\n}",".service-home{\n\tposition: relative;\n}\n\n.service-item{\n\ti{\n\t\tfont-size: 35px;\n\t\tfloat: left;\n\t\twidth: 65px;\n\t\theight: 120px;\n\t}\n\t\n}",".testimonial-content{\n\ttext-align: center;\n\n\timg{\n    \t// box-shadow: 0 20px 30px rgba(0, 0, 0, 0.1);\n\t}\n\tpadding: 25px;\n    position: relative;\n\n\ti{\n\t\tfont-size: 60px;\n\t}\n\n\tp{\n\t\tmargin-top: 30px;\n\t\tmargin-bottom: 25px;\n\t}\n\n}",".about-info{\n\th3{\n\t\tmargin-top: 15px;\n\t}\n\t\n}\n\n.progress-bar-content{\n\tmargin-bottom: 25px;\n\n\t.progress-title{\n\t\ttext-transform: capitalize;\n\t\tfont-size: 14px;\n\t\tcolor: $black;\n\t\tfont-weight: 600;\n\t\t\n\t}\n\n\t.progress-label{\n\t\tmargin-bottom: 15px;\n\t}\n\t.progress-bar{\n\t\tbackground: $black;\n\t}\n\n\t.progress-bar-units{\n\t\tcolor: $black;\n\t}\n}\n\n.about-list{\n\tline-height: 40px;\n\tli{\n\t\ttext-transform: capitalize;\n\t\tcolor: $black;\n\t}\n}\n\n\n.progress {\n  width: 100%;\n  overflow: visible;\n  position: relative;\n  margin: 0 0 35px 0;\n  border-radius: 0px;\n  height: 7px;\n  background-color: #f7f8f9;\n}\n\n.progress-bar {\n  position: absolute;\n  width: 0;\n  top: 0;\n  left: 0;\n  height: 100%;\n  background: #e1a34c;\n  border-radius: 0px;\n  transition: all 3s ease-in-out;\n}\n\n\n\n@include mobile{\n\t.cta{\n\t\tpadding-bottom: 0px;\n\t}\n}\n\n@include mobile-xs{\n\t.cta{\n\t\tpadding-bottom: 0px;\n\t}\n}\n\n@include tablet{\n\t.cta{\n\t\tpadding-bottom: 0px;\n\t}\n}","#map{\n\theight: 300px;\n\tmargin: 75px 0px;\n}\n\n.form-control{\n\tborder-radius: 0px;\n\theight: 45px;\n\tborder-color: $extra-color;\n\n\t&:focus{\n\t\tbox-shadow: none;\n\t\tborder-color: $primary-color;\n\t}\n}\n\ntextarea.form-control{\n\theight: auto;\n}\n\n.text-black{\n\tcolor: $black;\n}\n\n.contact-title {\n\th2{\n\t\tposition: relative;\n\t\tpadding-bottom: 30px;\n\n\t\t&:after {\n\n\t    position: absolute;\n\t    content: \"\";\n\t    left: 50%;\n\t    bottom: 0px;\n\t    width: 40px;\n\t    height: 2px;\n\t    margin-left: -25px;\n\t    background: $primary-color;\n\n\t}\n\t}\n}",".letter-spacing{\n\tletter-spacing: 1px;\n}\n\n\n.post{\n\t.image-content{\n\t\tposition: relative;\n\n\t\timg{\n\t\t\twidth: 100%;\n\t\t}\n\t}\n\n\t.author{\n\t\timg{\n\t\t\twidth: 40px;\n\t\t\theight: 40px;\n\t\t\tborder-radius: 100%;\n\t\t}\n\t}\n\n\t.post-content{\n\t\tmargin-top: 30px;\n\t\th4{\n\t\t\tmargin-top: 10px;\n\t\t\t-webkit-transition: all .35s ease;\n\t\t\t   -moz-transition: all .35s ease;\n\t\t\t    -ms-transition: all .35s ease;\n\t\t\t     -o-transition: all .35s ease;\n\t\t\t        transition: all .35s ease;\n\t\t}\n\n\t\ta:hover h4{\n\t\t\tcolor: $primary-color;\n\t\t}\n\t}\n}\n\n\n.pagination{\n\tmargin-top: 70px;\n\tli a{\n\t\tbackground: #f6f6f6;\n\t\tfont-size: 14px;\n\t\tfont-weight: 600;\n\t\tdisplay: inline-block;\n\t\tpadding: 9px 18px;\n\t\tcolor: #666666;\n\t\ttransition: .3s;\n\n\t\t&:hover{\n\t\t\tbackground: $primary-color;\n\t\t\tcolor: $white;\n\t\t}\n\t}\n\tli.active a{\n\t\tbackground: $primary-color;\n\t\tcolor: $white;\n\t}\n}\n\n\n// Sidebar\n// \n\n.sidebar-widget{\n\t.widget{\n\t\tpadding-left: 20px;\n\t}\n\t.widget-title{\n\t\ttext-transform: capitalize;\n\t\tposition: relative;\n\t\tpadding-bottom: 20px;\n\n\t\t&:after{\n\t\t\tposition: absolute;\n\t\t\tcontent:\"\";\n\t\t\tleft: 0px;\n\t\t\tbottom: 0px;\n\t\t\twidth: 30px;\n\t\t\theight: 2px;\n\t\t\tbackground: $black;\n\t\t}\n\t}\n\n\t.follow{\n\t\ta{\n\t\t\tmargin-right: 10px;\n\t\t}\n\t}\n\n\t.tags{\n\t\ta{\n\t\t\ttext-transform: capitalize;\n\t\t\tfont-size: 15px;\n\t\t\tpadding: 2px 13px;\n\t\t\tdisplay: inline-block;\n\t\t\tmargin-bottom: 8px;\n\t\t\tbackground:  $border-color;\n\t\t}\n\t}\n\n\t.category{\n\t\tul{\n\t\t\tline-height: 40px;\n\n\t\t\tli{\n\t\t\t\tfont-size: 15px;\n\t\t\t\ttext-transform: capitalize;\n\t\t\t}\n\t\t}\n\t}\n}\n.post-body{\n\tspan{\n\t\tfont-size: 13px;\n\t\tletter-spacing: 1px;\n\t}\n}\n\n\n/// SINGlE POSt\n\n.single-post{\n\tmargin-bottom: 70px;\n}\n.share{\n\tul li a{\n\t\tmargin-right: 20px;\n\t}\n}\n\n\n\n.mb-45{\n\tmargin-bottom: 45px;\n}\n\n.comments-text{\n\tp{\n\t\tfont-size: 14px;\n\t\tmargin-bottom: 10px;\n\t\tline-height: 26px;\n\t}\n}\n\n\n@include mobile{\n\t.media {\n\t    display: block;\n\n\t    img{\n\t    \tmargin-bottom: 10px;\n\t    }\n\t}\n}\n\n@include mobile-xs{\n\t.media {\n\t    display: block;\n\t     img{\n\t    \tmargin-bottom: 10px;\n\t    }\n\t}\n}\n@include tablet{\n\t.media {\n\t    display: block;\n\n\t     img{\n\t    \tmargin-bottom: 10px;\n\t    }\n\t}\n}",".footer{\n\tpadding: 30px 0px;\n\tbackground: $black;\n}\n.footer-widget{\n\n\ta{\n\t\tcolor: rgba(255,255,255,.5);\n\t\ttext-transform: capitalize;\n\t\t&:hover{\n\t\t\tcolor: $primary-color;\n\t\t}\n\t}\n}\n\t\n",".portfolio-card{\n    background:#fff;\n    border-radius:12px;\n    overflow:hidden;\n    box-shadow:0 5px 20px rgba(0,0,0,.08);\n}\n\n.portfolio-info{\n    padding:18px;\n}\n\n.portfolio-info h4{\n    margin-bottom:15px;\n    font-size:20px;\n    font-weight:600;\n}\n\n.portfolio-stats{\n    display:flex;\n    justify-content:space-between;\n    text-align:center;\n}\n\n.stat{\n    flex:1;\n}\n\n.number{\n    display:block;\n    font-size:24px;\n    font-weight:700;\n}\n\n.label{\n    display:block;\n    font-size:13px;\n    color:#777;\n}\n\n.portfolio-info{\n    padding:18px;\n}\n\n.project-stats{\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 10px;\n    margin-bottom: 1.3vw;\n}\n\n.project-description {\n    font-size: 0.9rem;\n    line-height: 1.5;\n    color: #6c757d;\n    border-top: 1px solid #eee;\n    padding-top: 12px;\n    margin-top: 10px;\n}\n\n.stat{\n    flex: 1;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    gap: 6px;\n    text-align: center;\n    font-size: 1.3vw;\n    font-weight: 500;\n}\n\n.portfolio-info{\n    padding: 24px 18px;\n}\n\n\n.project-stats{\n    display: flex;\n    justify-content: center;\n    gap: 1vw;\n}       \n\n.stat{\n    flex: 1;\n    display: flex;\n    flex-direction: column;    /* Icona sopra, testo sotto */\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    gap: 8px;\n    margin-top: 5px;\n}\n\n.stat i{\n    font-size: 1.2em;\n    color: #4a90e2;\n}\n\n.stat span{\n    font-size: 0.7em;\n    font-weight: 500;\n    white-space: nowrap;\n}\n\n\n\n.portfolio-card {\n    height: 460px;\n}\n\n.portfolio-card .image img {\n    height: 160px;\n    object-fit: cover;\n}\n\n.portfolio-info {\n    padding: 10px 12px 12px;\n}\n\n.project-title {\n    font-size: 1.5rem;\n    margin-top: 5px;\n    margin-bottom: 10px;\n\n    text-align: center;\n    font-weight:600;\n    line-height: 1.2em;\n}\n\n.project-stats {\n    font-size: 0.8rem;\n}\n\n.project-stats .stat {\n    margin-right: 8px;\n}\n\n.mb-4 {\n    margin-bottom: 1rem !important;\n}\n\n@media (max-width: 720px) {\n    .project-stats\n    {\n        margin-top: 20px;\n        margin-bottom: 0px;\n    }\n\n    .stat\n    {\n        font-size: 2.4vw;\n    }\n}",".portfolio-options\n{\n    margin-bottom: 1em !important;\n}\n\n/* ============================================\n   BANNER: contenitore principale\n   ============================================ */\n.banner {\n    position: relative;\n    min-height: 70vh;\n    display: flex;\n    align-items: center;\n    overflow: hidden;\n}\n\n/* ============================================\n   VIDEO BACKGROUND: colonna centrata\n   ============================================ */\n.video-background {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    width: 95%;              /* 👈 LARGHEZZA DELLA COLONNA (regolabile) */\n    height: 95%;             /* 👈 ALTEZZA DELLA COLONNA (regolabile) */\n    min-width: 70%;\n    max-width: 1200px;       /* Larghezza massima */\n    max-height: 800px;       /* Altezza massima */\n    z-index: 0;\n    overflow: hidden;\n    border-radius: 20px;     /* Angoli arrotondati (opzionale) */\n    box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n}\n\n/* ============================================\n   VIDEO: centrato e tagliato all'interno della colonna\n   ============================================ */\n.video-background video {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    min-width: 100%;\n    min-height: 100%;\n    width: auto;\n    height: auto;\n    object-fit: cover;\n    opacity: 60%;\n}\n\n/* Meta' schermo */\n@media (max-width: 720px) {\n    .video-background {\n        max-height: 80%;\n        max-width: 100%;\n    }\n    \n    .banner .cd-headline\n    {\n        font-size: 24px !important;\n    }\n    \n    .section.banner\n    {\n        padding: 0px;\n        min-height: 50vh;\n    }\n\n    body > section.portfolio > div > div.row.mb-5\n    {\n        margin-bottom: 15px !important;\n    }\n}\n/* \n==================================\nTelefono\n==================================\n*/\n@media (max-width: 520px)\n{\n    .video-background {\n        max-height: 100%;\n        max-width: 100%;\n        border-radius: 0px;\n\n        width: 100%;\n        height: 100%;\n        box-shadow: inset 0px 0px 30px 30px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n    }\n\n    .section.banner\n    {\n        padding: 0px;\n        min-height: 30vh;\n    }\n\n    body > section.portfolio > div > div.row.mb-5\n    {\n        margin-bottom: 15px !important;\n    }\n    /*\n    ==================================\n    Portfolio-home\n    ==================================\n    */\n    label.btn {\n        font-size: 13px;\n        padding: 20px 10px 10px 0px !important;\n    }\n\n    p.short-text{\n        display: contents;\n    }\n\n    p.full-text{\n        display:none;\n    }\n\n    .stat {\n        font-size: 3vw;\n    }\n}\n@media (min-width: 521px)\n{\n    p.short-text\n    {\n        display:none;\n    }\n    \n    p.full-text{\n        display:contents;\n    }\n\n}\n\n\n\n\n/* ============================================\n   CONTENUTO TESTUALE: sopra il video\n   ============================================ */\n.banner .container {\n    position: relative;\n    z-index: 1;\n    width: 100%;\n}\n\n/* Colonna del testo centrata con larghezza controllata */\n.banner .container .col-lg-10 {\n    margin: 0 auto;\n    float: none;\n}\n\n/* Testo in contrasto con il video */\n.banner h2,\n.banner p {\n    color: white;\n    text-shadow: 0 2px 15px rgba(0, 0, 0, 0.7);\n}\n\n\n\n\n\n.copy-btn {\n    background: transparent;\n    border: none;\n    padding: 0;\n    cursor: pointer;\n    color: inherit;          /* Eredita il colore dal testo circostante */\n    font: inherit;           /* Eredita il font */\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    transition: transform 0.2s ease, opacity 0.2s ease;\n}\n\n.copy-btn:hover {\n    color: #f44336;\n}\n\n.toast {\n    position: fixed;\n    bottom: 30px;\n    left: 50%;\n    transform: translateX(-50%) translateY(100px);\n    background: #ffffff;\n    color: #222;\n    padding: 14px 32px;\n    border-radius: 30px;\n    font-size: 0.95rem;\n    font-weight: 500;\n    letter-spacing: 0.3px;\n    box-shadow: 0 15px 50px rgba(0, 0, 0, 0.35);\n    opacity: 0;\n    transition: opacity 0.4s ease, transform 0.4s ease;\n    z-index: 9999;\n    pointer-events: none;\n    white-space: nowrap;\n}\n\n.toast.show {\n    opacity: 1;\n    transform: translateX(-50%) translateY(0);\n}\n\n\n\n\n/* Cambiano in base alla grandezza del dispositivo */\n/* Su schermi piccoli, abbrevia il testo */\n@media (max-width: 768px) {\n    .stat .full-text {\n        display: none;\n    }\n    .stat .short-text {\n        display: inline;\n    }\n}\n\n@media (min-width: 769px) {\n    .stat .full-text {\n        display: inline;\n    }\n    .stat .short-text {\n        display: none;\n    }\n}\n\n@media (max-width: 991px)\n{\n    .footer-widget\n    {\n        margin-top: 1em !important;\n    }\n}\n\n@media (max-width: 768px) {\n    .navbar-nav {\n        flex-wrap: nowrap !important;\n    }\n    \n    .navbar-nav .nav-item {\n        white-space: nowrap;\n    }\n}",".rainbow-icon {\n    display: inline-block;\n    font-size: 1.2rem;\n    background: linear-gradient(90deg, #ff0000, #ff7700, #ffff00, #00ff00, #0000ff, #8b00ff, #ff0000);\n    background-size: 300% 100%;\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n    background-clip: text;\n    animation: rainbowScroll 4s linear infinite, floatXY 1s linear infinite;\n}\n\n@keyframes rainbowScroll {\n    0% { background-position: 0% 50%; }\n    100% { background-position: 300% 50%; }\n}\n\n@keyframes floatXY {\n    /*0%, 100% { transform: rotate(0deg); }\n    25% { transform: rotate(-10deg);}\n    50% { transform: rotate(0deg); }\n    75% { transform: rotate(10deg); }*/\n\n    0%, 100% { transform: scale(1); }\n    50% { transform: scale(1.2); }\n\n\n}",".jump-text {\n    font-size: 2em;\n    display: inline-block;\n}\n\n.jump-text span {\n    display: inline-block;\n    animation: jump 0.8s ease-in-out infinite, rainbow 3s linear infinite;\n}\n\n.jump-text span:nth-child(1) { animation-delay: 0s, 0s; }\n.jump-text span:nth-child(2) { animation-delay: 0.1s, 0.1s; }\n.jump-text span:nth-child(3) { animation-delay: 0.2s, 0.2s; }\n.jump-text span:nth-child(4) { animation-delay: 0.3s, 0.3s; }\n.jump-text span:nth-child(5) { animation-delay: 0.4s, 0.4s; }\n.jump-text span:nth-child(6) { animation-delay: 0.5s, 0.5s; }\n.jump-text span:nth-child(7) { animation-delay: 0.6s, 0.6s; }\n.jump-text span:nth-child(8) { animation-delay: 0.7s, 0.7s; }\n.jump-text span:nth-child(9) { animation-delay: 0.8s, 0.8s; }\n.jump-text span:nth-child(10) { animation-delay: 0.9s, 0.9s; }\n.jump-text span:nth-child(11) { animation-delay: 1s, 1s; }\n.jump-text span:nth-child(12) { animation-delay: 1.1s, 1.1s; }\n.jump-text span:nth-child(13) { animation-delay: 1.2s, 1.2s; }\n.jump-text span:nth-child(14) { animation-delay: 1.3s, 1.3s; }\n.jump-text span:nth-child(15) { animation-delay: 1.4s, 1.4s; }\n.jump-text span:nth-child(16) { animation-delay: 1.5s, 1.5s; }\n.jump-text span:nth-child(17) { animation-delay: 1.6s, 1.6s; }\n.jump-text span:nth-child(18) { animation-delay: 1.7s, 1.7s; }\n.jump-text span:nth-child(19) { animation-delay: 1.8s, 1.8s; }\n.jump-text span:nth-child(20) { animation-delay: 1.9s, 1.9s; }\n\n@keyframes jump {\n    0%, 100% { transform: translateY(0); }\n    50% { transform: translateY(-8px); }\n}\n\n@keyframes rainbow {\n    0% { color: #ff0000; }\n    17% { color: #ff7700; }\n    33% { color: #ffff00; }\n    50% { color: #00ff00; }\n    67% { color: #0000ff; }\n    83% { color: #8b00ff; }\n    100% { color: #ff0000; }\n}",".project-description-full {\n    padding: 40px 0;\n    border-top: 2px solid #e8e8e8;\n}\n\n.border-line {\n    width: 50%;\n    height: 2px;\n    background: #e8e8e8;\n    margin: 0 auto;\n}\n\n.project-description-full h3 {\n    font-size: 1.8rem;\n    font-weight: 700;\n    letter-spacing: -0.5px;\n    margin-bottom: 20px;\n    color: #1a1a1a;\n}\n\n.project-description-full p {\n    font-size: 1.05rem;\n    line-height: 1.9;\n    color: #444;\n    margin-bottom: 18px;\n}","// base icon class definition\n// -------------------------\n@use 'variables' as v;\n@use 'mixins' as m;\n\n.#{v.$css-prefix}-solid,\n.#{v.$css-prefix}-regular,\n.#{v.$css-prefix}-brands,\n.#{v.$css-prefix}-classic,\n.fas,\n.far,\n.fab,\n.#{v.$css-prefix} {\n  @include m.fa-icon();\n}\n\n:is(\n  .fas,\n  .far,\n  .fab,\n  .#{v.$css-prefix}-solid,\n  .#{v.$css-prefix}-regular,\n  .#{v.$css-prefix}-brands,\n  .#{v.$css-prefix}-classic,\n  .fa\n)::before {\n  content: var(#{v.$icon-property})/\"\";\n}\n\n@supports not (content: ''/'') {\n:is(\n  .fas,\n  .far,\n  .fab,\n  .#{v.$css-prefix}-solid,\n  .#{v.$css-prefix}-regular,\n  .#{v.$css-prefix}-brands,\n  .#{v.$css-prefix}-classic,\n  .fa\n)::before {\n    content: var(#{v.$icon-property});\n  }\n}","// mixins\n// --------------------------\n@use 'variables' as v;\n\n// base rendering for an icon\n@mixin fa-icon($family: v.$family) {\n  --_#{v.$css-prefix}-family: var(--#{v.$css-prefix}-family, var(--#{v.$css-prefix}-style-family, '#{$family}'));\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  display: var(--#{v.$css-prefix}-display, #{v.$display});\n  font-family: var(--_#{v.$css-prefix}-family);\n  font-feature-settings: normal;\n  font-style: normal;\n  font-synthesis: none;\n  font-variant: normal;\n  font-weight: var(--#{v.$css-prefix}-style, #{v.$style});\n  line-height: 1;\n  text-align: center;\n  text-rendering: auto;\n  width: var(--#{v.$css-prefix}-width, #{v.$fw-width});\n}\n\n// sets relative font-sizing and alignment (in _sizing)\n@mixin fa-size ($font-size) {\n  font-size: calc(#{$font-size} / #{v.$size-scale-base} * 1em); /* converts a #{$font-size}px size into an em-based value that's relative to the scale's #{v.$size-scale-base}px base */\n  line-height: calc(1 / #{$font-size} * 1em); /* sets the line-height of the icon back to that of it's parent */\n  vertical-align: calc(((6 / #{$font-size}) - (3 / 8)) * 1em); /* vertically centers the icon taking into account the surrounding text's descender */\n}\n","// sizing icons\n// -------------------------\n@use 'variables' as v;\n@use 'mixins' as m;\n\n// literal magnification scale\n@for $i from 1 through 10 {\n  .#{v.$css-prefix}-#{$i}x {\n    font-size: $i * 1em;\n  }\n}\n\n// step-based scale (with alignment)\n@each $size, $value in v.$sizes {\n  .#{v.$css-prefix}-#{$size} {\n     @include m.fa-size($value);\n  }\n}\n","// icon widths\n// -------------------------\n@use 'variables' as v;\n\n.#{v.$css-prefix}-width-auto {\n  --#{v.$css-prefix}-width: auto;\n}\n\n.#{v.$css-prefix}-fw,\n.#{v.$css-prefix}-width-fixed {\n  --#{v.$css-prefix}-width: #{v.$fw-width};\n}\n\n.#{v.$css-prefix}-canvas-square {\n  padding-block: 0.125em;\n  margin-block-end: -.125em;\n}\n\n.#{v.$css-prefix}-canvas-roomy {\n  padding-block: 0.25em;\n  padding-inline: .125em;\n  margin-block-end: -.25em;\n  box-sizing: content-box;\n}\n","// icons in a list\n// -------------------------\n@use 'variables' as v;\n\n.#{v.$css-prefix}-ul {\n  list-style-type: none;\n  margin-inline-start: var(--#{v.$css-prefix}-li-margin, #{v.$li-margin});\n  padding-inline-start: 0;\n\n  > li { position: relative; }\n}\n\n.#{v.$css-prefix}-li {\n  inset-inline-start: calc(-1 * var(--#{v.$css-prefix}-li-width, #{v.$li-width}));\n  position: absolute;\n  text-align: center;\n  width: var(--#{v.$css-prefix}-li-width, #{v.$li-width});\n  line-height: inherit;\n}\n","//  bordered icons\n// -------------------------\n@use 'variables' as v;\n\n/* Heads Up: Bordered Icons will not be supported in the future!\n  - This feature will be deprecated in the next major release of Font Awesome (v8)!\n  - You may continue to use it in this version *v7), but it will not be supported in Font Awesome v8.\n*/\n\n/* Notes:\n* --@{v.$css-prefix}-border-width = 1/16 by default (to render as ~1px based on a 16px default font-size)\n* --@{v.$css-prefix}-border-padding =\n  ** 3/16 for vertical padding (to give ~2px of vertical whitespace around an icon considering it's vertical alignment)\n  ** 4/16 for horizontal padding (to give ~4px of horizontal whitespace around an icon)\n*/\n\n.#{v.$css-prefix}-border {\n  border-color: var(--#{v.$css-prefix}-border-color, #{v.$border-color});\n  border-radius: var(--#{v.$css-prefix}-border-radius, #{v.$border-radius});\n  border-style: var(--#{v.$css-prefix}-border-style, #{v.$border-style});\n  border-width: var(--#{v.$css-prefix}-border-width, #{v.$border-width});\n  box-sizing: var(--#{v.$css-prefix}-border-box-sizing, #{v.$border-box-sizing});\n  padding: var(--#{v.$css-prefix}-border-padding, #{v.$border-padding});\n}\n","// pulled icons\n// -------------------------\n@use 'variables' as v;\n\n.#{v.$css-prefix}-pull-left,\n.#{v.$css-prefix}-pull-start {\n  float: inline-start;\n  margin-inline-end: var(--#{v.$css-prefix}-pull-margin, #{v.$pull-margin});\n}\n\n.#{v.$css-prefix}-pull-right,\n.#{v.$css-prefix}-pull-end {\n  float: inline-end;\n  margin-inline-start: var(--#{v.$css-prefix}-pull-margin, #{v.$pull-margin});\n}\n","// animating icons\n// --------------------------\n@use 'variables' as v;\n\n.#{v.$css-prefix}-beat {\n  animation-name: #{v.$css-prefix}-beat;\n  animation-delay: var(--#{v.$css-prefix}-animation-delay, 0s);\n  animation-direction: var(--#{v.$css-prefix}-animation-direc